(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" focusable="false"><use href="/assets/icons.svg#${name}"></use></svg>`;
const course=()=>window.BoraCourses[0];
const lessonPhoto=l=>window.BoraLessonPhotos?.[l.id]||{src:'/assets/rio-panorama.webp',place:'Бразилия'};
function lessonFigure(l){const p=lessonPhoto(l);return `<figure class="lesson-landscape"><img src="${p.src}" alt="${esc(p.place)}" width="960" height="480"><figcaption><strong>${esc(p.place)}</strong><span>Твоя следующая остановка</span></figcaption>${p.url?`<details class="photo-credit"><summary>Об этой фотографии</summary><p><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.author)} · ${esc(p.source)}</a> · <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.license)}</a>. Кадрирование и сжатие для сайта.</p></details>`:''}</figure>`}
let disposeCarousel=()=>{};
function stop(){disposeCarousel();disposeCarousel=()=>{}}
function carousel(){const track=document.querySelector('#lesson-carousel-track');if(!track)return;const prev=document.querySelector('#carousel-prev'),next=document.querySelector('#carousel-next'),label=document.querySelector('#carousel-position');const update=()=>{const max=Math.max(0,track.scrollWidth-track.clientWidth);prev.disabled=track.scrollLeft<=2;next.disabled=track.scrollLeft>=max-2;const children=track.children,bounds=track.getBoundingClientRect(),visible=Array.from(children).map((node,index)=>{const r=node.getBoundingClientRect();return r.right>bounds.left+8&&r.left<bounds.right-8?index+1:0}).filter(Boolean);const text=`Уроки ${visible[0]||1}–${visible.at(-1)||children.length} из ${children.length}`;if(label.textContent!==text)label.textContent=text};const move=direction=>track.scrollBy({left:direction*track.clientWidth,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});prev.onclick=()=>move(-1);next.onclick=()=>move(1);track.onscroll=update;track.onkeydown=e=>{if(e.target!==track)return;if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home'||e.key==='End')track.scrollTo({left:e.key==='Home'?0:track.scrollWidth,behavior:'instant'});else move(e.key==='ArrowRight'?1:-1)}};window.addEventListener?.('resize',update);disposeCarousel=()=>{window.removeEventListener?.('resize',update);track.onscroll=null;track.onkeydown=null};update()}

const norm=s=>String(s??'').normalize('NFD').replace(/\p{M}/gu,'').toLocaleLowerCase('ru-RU').trim();
const images=['rio-palms','brazil-colors','rio-coast','rio-panorama','rio-coast'];
function stats(u){const c=course(),done=c.lessons.filter(l=>u.courseProgress?.['pt/'+l.id]?.done).length;return {done,total:c.lessons.length,percent:Math.round(done/c.lessons.length*100),due:window.BoraStudy?.due(u)||[],next:window.BoraStudy?.next(u)||c.lessons[0]}}
function home(u){const c=course(),s=stats(u),start=!u.onboarded?'start':!u.diagnosis?'diagnosis':'courses/pt/'+s.next.id,cta=!u.onboarded?'Начать своё путешествие':!u.diagnosis?'Найти свой уровень':'Продолжить обучение';return `<div class="welcome-line"><div><span class="overline">PORTUGUÊS DO BRASIL</span><h1>${u.onboarded?`Oi, ${esc(u.name||'друг')}<span class="greeting-dot">.</span>`:'Бразилия ближе, чем кажется.'}</h1><p>${u.onboarded?'Рад тебя видеть. Давай сегодня ещё немного по-португальски?':'Понятный язык. Настоящие разговоры. Твой собственный темп.'}</p></div><span class="welcome-tag">${icon('sun')} Um passo de cada vez</span></div><section class="brazil-hero"><img class="brazil-hero-image" src="/assets/rio-panorama.webp" alt="Зелёные горы Рио-де-Жанейро и океан" width="966" height="544" fetchpriority="high"><div class="brazil-hero-shade"></div><div class="brazil-hero-copy"><span class="glass-label"><img src="/assets/brazil-flag.webp" width="24" height="16" alt=""> Твоя маленькая Бразилия</span><h2>Большое путешествие<br>начинается с <em>Oi!</em></h2><p>Учись говорить, понимать и чувствовать язык.<br>По одной простой фразе за раз.</p><a class="btn yellow" href="#${start}">${cta} ${icon('arrow-up-right')}</a></div><span class="hero-location">${icon('compass')} Rio de Janeiro, Brasil <span>22°54′ S · 43°12′ W</span></span></section><div class="home-facts"><span>${icon('book-open')} <strong>30</strong> коротких уроков</span><span>${icon('headphones')} Бразильское произношение</span><span>${icon('clock-3')} 10–15 минут в день</span></div><section class="today-layout"><article class="next-card"><div class="section-kicker">${icon('compass')} ТВОЙ СЛЕДУЮЩИЙ ШАГ <span>${u.onboarded?'Продолжаем':'Начинаем'}</span></div><h2>${!u.onboarded?'Давай познакомимся':!u.diagnosis?'Найдём твою точку старта':esc(s.next.title)}</h2><p>${!u.onboarded?'Расскажи о своей цели. Подберём комфортное начало — даже если ты пока не знаешь ни слова.':!u.diagnosis?'Несколько простых заданий помогут выбрать комфортную сложность. Здесь можно отвечать «Не знаю».':esc(s.next.scene)}</p><div class="next-card-bottom"><a class="text-action" href="#${start}">${u.onboarded&&u.diagnosis?'Открыть урок':'Сделать первый шаг'} ${icon('arrow-right')}</a><span>${icon('clock-3')} ${u.onboarded&&u.diagnosis?'5–10 минут':'Без спешки'}</span></div><div class="mini-progress"><div><span>Твой маршрут</span><strong>${s.done} / ${s.total} уроков</strong></div><progress value="${s.done}" max="${s.total}" aria-label="Прогресс курса"></progress></div></article><article class="coach-card"><div class="coach-orb">${icon('messages-square')}</div><span class="overline">BORA · ТВОЙ ПОМОЩНИК</span><h2>А давай поговорим?</h2><p>Без страха ошибиться. С простыми объяснениями и маленькими подсказками.</p><div class="coach-phrase"><span lang="pt-BR">Oi! Tudo bem?</span><span>Привет! Как дела?</span><div class="sound-bars" aria-hidden="true">${[12,24,18,32,40,22,30,16,26,12].map(h=>`<i style="height:${h}px"></i>`).join('')}</div></div><a class="btn coach-button" href="#practice/${s.next.id}">${icon('mic')} Потренировать разговор ${icon('arrow-up-right')}</a></article></section>${s.due.length?`<section class="review-strip"><div class="review-symbol">${icon('rotate-ccw')}</div><div><h3>Вспомним то, что уже знаешь?</h3><p>На сегодня ${s.due.length} тем для закрепления. Начнём с «${esc(s.due[0].l.title)}».</p></div><a class="btn alt" href="#review/pt/${s.due[0].l.id}">Повторить ${icon('arrow-right')}</a></section>`:''}<div class="section-head"><div><span class="overline">ИЗ ПЕРВЫХ СЛОВ — В НАСТОЯЩУЮ ЖИЗНЬ</span><h2>Твой маршрут по Бразилии</h2></div><a class="text-action" href="#courses/pt">Весь курс ${icon('arrow-up-right')}</a></div><section class="lesson-carousel" aria-label="Все 30 уроков"><div class="carousel-toolbar"><span id="carousel-position" role="status" aria-live="polite">Все 30 уроков · листай маршрут</span><div><button class="carousel-arrow" id="carousel-prev" aria-label="Предыдущие уроки">${icon('arrow-left')}</button><button class="carousel-arrow" id="carousel-next" aria-label="Следующие уроки">${icon('arrow-right')}</button></div></div><ul class="module-previews lesson-carousel-track" id="lesson-carousel-track" tabindex="0" aria-label="Уроки: используй стрелки влево и вправо">${c.lessons.map((l,i)=>{const p=lessonPhoto(l);return `<li><a class="module-preview" href="#courses/pt/${l.id}"><div class="module-photo"><img src="${p.src}" alt="${esc(p.place)}" loading="lazy" width="480" height="300"><span>УРОК ${String(i+1).padStart(2,'0')} · ${esc(p.place)}</span></div><div class="module-copy"><h3>${esc(l.title)}</h3><p>${esc(l.module)} · 5–10 минут</p>${icon('arrow-up-right')}</div></a></li>`}).join('')}</ul></section><div class="quiet-note">${icon('sparkles')} Понимать, а не заучивать. Объяснения на русском, примеры — из жизни в Бразилии.</div><p class="photo-sources-link"><a href="/photo-credits.html">Фотографии: авторы и лицензии</a></p>`}
function filterLessons(lessons,records,{q='',module='all',status='all'}={}){const term=norm(q);return lessons.filter(l=>{const r=records?.['pt/'+l.id],state=r?.done?'done':r?.stage?'started':'new';return (module==='all'||l.module===module)&&(status==='all'||state===status)&&(!term||norm([l.title,l.topic,l.scene,l.idea,...(l.examples||[]).flat()].join(' ')).includes(term))})}
function catalog(u,c=course()){const s=stats(u),params=new URLSearchParams(location.hash.split('?')[1]||''),mi=params.get('module')||'all',q=(params.get('q')||'').slice(0,100),status=['all','new','started','done'].includes(params.get('status'))?params.get('status'):'all';return `<div class="page-heading"><span class="overline">ТВОЯ ПРОГРАММА ОБУЧЕНИЯ</span><h1>От первого <em>Oi!</em><br>к своим историям.</h1><p>Пять остановок на пути к общению. Выбирай тему или продолжай свой маршрут.</p></div><section class="course-banner"><img src="/assets/rio-coast.webp" alt="Побережье Рио-де-Жанейро" width="700" height="440"><div><span class="glass-label">🇧🇷 Português do Brasil</span><h2>Бразильский португальский</h2><p>Простые объяснения на русском.<br>Фразы, которые хочется использовать.</p><a class="btn yellow" href="#courses/pt/${s.next.id}">Продолжить обучение ${icon('arrow-right')}</a><div class="banner-progress"><progress value="${s.done}" max="${s.total}" aria-label="Прогресс курса"></progress><span>${s.done} из ${s.total} уроков</span></div></div></section>${u.diagnosis?`<div class="route-note">${icon('target')} <span>Твой ориентир: <strong>${esc(u.diagnosis.level)}</strong>. Это предварительный маршрут, а не официальный уровень. <a href="#result">Подробнее</a></span></div>`:''}<section class="lesson-browser" aria-label="Поиск и выбор урока"><div class="section-head"><h2>Выбери свою тему</h2><span id="lesson-count" class="small" role="status" aria-live="polite">${c.lessons.length} уроков</span></div><div class="lesson-filters"><label class="search-field">${icon('search')}<input id="lesson-search" type="search" maxlength="100" value="${esc(q)}" placeholder="Найти тему: кафе, прошлое, знакомство…" aria-label="Поиск по урокам"></label><label class="status-filter">${icon('sliders-horizontal')}<select id="lesson-status" aria-label="Состояние уроков">${[['all','Все уроки'],['new','Новые'],['started','Начатые'],['done','Пройденные']].map(([v,label])=>`<option value="${v}" ${v===status?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="module-filters" role="group" aria-label="Модуль курса"><button type="button" data-module="all" aria-pressed="${mi==='all'}">Весь маршрут</button>${c.modules.map((m,i)=>`<button type="button" data-module="${i}" aria-pressed="${mi===String(i)}"><span>${String(i+1).padStart(2,'0')}</span> ${esc(m.title)}</button>`).join('')}</div><div class="lesson-card-grid">${c.lessons.map((l,i)=>{const r=u.courseProgress?.['pt/'+l.id],done=r?.done,started=r?.stage&&!done;return `<article class="lesson-card ${done?'is-complete':''}" data-lesson-id="${l.id}"><a href="#courses/pt/${l.id}"><div class="lesson-card-photo"><img src="${lessonPhoto(l).src}" alt="${esc(lessonPhoto(l).place)}" width="480" height="260" loading="lazy"><span>${esc(lessonPhoto(l).place)}</span></div><div class="lesson-card-top"><span class="lesson-index">${done?icon('check'):String(i+1).padStart(2,'0')}</span><span class="lesson-state">${done?'Пройдено':started?'Продолжаем':'5–10 минут'}</span>${icon('arrow-up-right')}</div><span class="lesson-module">${esc(l.module)}</span><h3>${esc(l.title)}</h3><p>${esc(l.scene)}</p><span class="lesson-topic">${icon('book-open')} ${esc(l.topic)}</span></a></article>`}).join('')}</div><div id="lesson-empty" class="empty-search" hidden>${icon('search')}<h3>Такой темы пока не нашли</h3><p>Попробуй другое слово или сбрось фильтры.</p><button class="btn alt" id="reset-filters">Показать весь маршрут</button></div></section><div class="quiet-note">${icon('circle-help')} Курс — основа для общения. Подготовка к Celpe-Bras дополнительно требует аудирования, развёрнутого письма и устной практики.</div>`}
let focus=false;
function focusButton(){return `<button class="btn alt focus-button" id="study-focus" aria-pressed="${focus}">${icon(focus?'minimize-2':'maximize-2')} ${focus?'Обычный вид':'Без отвлечений'}</button>`}
function steps(stage){return `<div class="lesson-stepper" aria-label="Этапы урока">${['Разобраться','Выбрать','Проверить','Написать','Поговорить'].map((text,i)=>`<span class="${i===stage?'current':i<stage?'passed':''}" ${i===stage?'aria-current="step"':''}><b>${i<stage?'✓':i+1}</b><span>${text}</span></span>`).join('')}</div>`}
function applyFocus(){document.body?.classList.toggle('study-focus',focus);const button=document.querySelector('#study-focus');if(button){button.setAttribute('aria-pressed',String(focus));button.innerHTML=icon(focus?'minimize-2':'maximize-2')+(focus?' Обычный вид':' Без отвлечений')}}
function refresh(route){if(!document.body)return;const skip=document.querySelector('.skip-link');if(skip)skip.onclick=e=>{e.preventDefault();document.querySelector('#app')?.focus()};const isLesson=route==='courses'&&location.hash.split('?')[0].split('/').length>=3;document.body.dataset.route=route;document.body.dataset.lesson=String(isLesson);if(!isLesson)focus=false;applyFocus();document.querySelectorAll('[data-nav]').forEach(a=>{const key=a.dataset.nav,current=key===(['review','courses'].includes(route)?'courses':['practice','live'].includes(route)?'assistant':route);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const caption=document.querySelector('#page-caption');if(caption)caption.textContent=({home:'Твоя маленькая Бразилия',courses:'Твой маршрут',progress:'Каждый шаг считается',assistant:'Разберёмся вместе',practice:'Время поговорить',account:'Твой аккаунт',start:'Давай познакомимся',review:'Вспомним вместе',diagnosis:'Твоя точка старта',result:'Твой маршрут',live:'Живой разговор'}[route]||'Português do Brasil')}
function bind(u){carousel();const search=document.querySelector('#lesson-search');if(search){const c=course(),params=new URLSearchParams(location.hash.split('?')[1]||'');let module=params.get('module')||'all';const status=document.querySelector('#lesson-status');const apply=()=>{const mod=module==='all'?'all':c.modules[Number(module)]?.title||'all';const ids=new Set(filterLessons(c.lessons,u.courseProgress,{q:search.value,module:mod,status:status.value}).map(l=>l.id));document.querySelectorAll('[data-lesson-id]').forEach(card=>card.hidden=!ids.has(card.dataset.lessonId));document.querySelector('#lesson-count').textContent=`Найдено: ${ids.size} из ${c.lessons.length}`;document.querySelector('#lesson-empty').hidden=!!ids.size;document.querySelectorAll('[data-module]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.module===module)));const p=new URLSearchParams();if(search.value)p.set('q',search.value);if(module!=='all')p.set('module',module);if(status.value!=='all')p.set('status',status.value);history.replaceState(null,'','#courses/pt'+(p.size?'?'+p.toString():''))};search.oninput=apply;status.onchange=apply;document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{module=b.dataset.module;apply()});document.querySelector('#reset-filters').onclick=()=>{module='all';search.value='';status.value='all';apply();search.focus()};apply()}const button=document.querySelector('#study-focus');if(button)button.onclick=()=>{focus=!focus;applyFocus()}}
window.BoraUI={home,catalog,lessonPhoto,lessonFigure,stop,filterLessons,icon,focusButton,steps,refresh,bind,esc};
})();
